css:
.bop-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}
.bop-sim-header {
    border-left: 4px solid #00ff88;
    padding: 20px 28px;
    margin-bottom: 24px;
    background: rgba(0,255,136,0.05);
}
.bop-sim-header h1 {
    color: #00ff88;
    font-size: 1.4rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: 0;
}
.bop-sim-subtitle {
    color: #6b7280;
    font-size: 0.85rem;
    margin-top: 8px;
    letter-spacing: 0.08em;
}
.bop-sim-period-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 20px;
    padding: 14px 20px;
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
}
.bop-sim-period-counter {
    color: #00bfff;
    font-size: 0.8rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}
.bop-sim-period-counter span {
    color: #e0e6f0;
    font-weight: 700;
    margin: 0 4px;
}
.bop-sim-round-title {
    color: #ffb347;
    font-size: 1.05rem;
    font-weight: 600;
    letter-spacing: 0.04em;
}
.bop-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.bop-sim-status-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
}
.bop-sim-status-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.bop-sim-label {
    color: #6b7280;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}
.bop-sim-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #00ff88;
    line-height: 1.1;
}
.bop-sim-briefing {
    background: #0d1322;
    border: 1px solid #1f2d3d;
    border-left: 4px solid #ffb347;
    border-radius: 6px;
    padding: 20px 24px;
    margin-bottom: 24px;
}
.bop-sim-briefing h3 {
    color: #ffb347;
    font-size: 0.85rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 12px;
}
.bop-sim-briefing #briefingText {
    color: #e0e6f0;
    font-size: 0.95rem;
    line-height: 1.6;
}
.bop-sim-ledger {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0;
    margin-bottom: 24px;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    overflow: hidden;
}
.bop-sim-ledger-side {
    background: #111827;
    padding: 18px 22px;
}
.bop-sim-ledger-current {
    border-right: 1px solid #1f2d3d;
}
.bop-sim-ledger-side h4 {
    color: #00bfff;
    font-size: 0.78rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 14px;
    border-bottom: 1px solid #1f2d3d;
    padding-bottom: 10px;
}
.bop-sim-ledger-financial h4 {
    color: #ffb347;
}
.bop-sim-ledger-side div {
    font-size: 0.88rem;
    padding: 6px 0;
    color: #9ca3af;
    border-bottom: 1px dashed #1a2434;
}
.bop-sim-ledger-side div:last-child {
    border-bottom: none;
}
.bop-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 20px;
}
.bop-sim-controls h3 {
    color: #00ff88;
    font-size: 0.9rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    margin-bottom: 16px;
}
.bop-sim-instruction {
    color: #9ca3af;
    font-size: 0.9rem;
    margin-bottom: 14px;
    font-style: italic;
}
.bop-sim-transaction {
    background: #0d1322;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 14px 16px;
    margin-bottom: 10px;
    transition: border-color 0.2s ease;
}
.bop-sim-transaction:hover {
    border-color: #00ff88;
}
.bop-sim-transaction-desc {
    color: #e0e6f0;
    font-size: 0.92rem;
    margin-bottom: 10px;
    line-height: 1.5;
}
.bop-sim-q {
    margin-bottom: 14px;
}
.bop-sim-controls label {
    display: block;
    color: #9ca3af;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 6px;
}
.bop-sim-controls input[type="number"],
.bop-sim-controls input[type="text"],
.bop-sim-controls select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
}
.bop-sim-controls select option {
    background: #111827;
    color: #e0e6f0;
}
.bop-sim-controls input:focus,
.bop-sim-controls select:focus {
    outline: none;
    border-color: #00ff88;
    box-shadow: 0 0 10px rgba(0,255,136,0.25);
}
.bop-sim-checkbox-group {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 10px;
    margin-top: 10px;
    margin-bottom: 16px;
}
.bop-sim-policy-option {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #0d1322;
    border: 1px solid #2d3f55;
    border-radius: 6px;
    padding: 14px;
    cursor: pointer;
    color: #e0e6f0;
    font-size: 0.88rem;
    text-transform: none;
    letter-spacing: normal;
    transition: border-color 0.2s ease, background 0.2s ease;
}
.bop-sim-policy-option:hover {
    border-color: #00bfff;
    background: #101a32;
}
.bop-sim-policy-option input[type="checkbox"] {
    margin-top: 3px;
    accent-color: #00ff88;
}
.bop-sim-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 24px;
}
.bop-sim-actions .btn-primary {
    background: #00ff88;
    border-color: #00ff88;
    color: #0a0f1e;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    padding: 12px 30px;
    border-radius: 4px;
    box-shadow: 0 0 14px rgba(0,255,136,0.2);
}
.bop-sim-actions .btn-primary:hover {
    background: #00cc6f;
    border-color: #00cc6f;
    box-shadow: 0 0 20px rgba(0,255,136,0.35);
}
.bop-sim-actions .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #9ca3af;
    padding: 10px 20px;
    border-radius: 4px;
}
.bop-sim-actions .btn-outline-secondary:hover {
    background: #111827;
    color: #e0e6f0;
    border-color: #3d526b;
}
.bop-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 20px;
    overflow-x: auto;
}
.bop-sim-history h3 {
    color: #00bfff;
    font-size: 0.85rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 12px;
}
.bop-sim-history table {
    color: #e0e6f0;
    font-size: 0.85rem;
    margin-bottom: 0;
    width: 100%;
}
.bop-sim-history table thead {
    background: #0d1322;
}
.bop-sim-history table th {
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-size: 0.68rem;
    border-color: #1f2d3d;
    padding: 10px;
}
.bop-sim-history table td {
    border-color: #1f2d3d;
    padding: 10px;
}
.bop-sim-chart {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    height: 340px;
}
@media (max-width: 768px) {
    .bop-sim-container {
        padding: 14px;
    }
    .bop-sim-ledger {
        grid-template-columns: 1fr;
    }
    .bop-sim-ledger-current {
        border-right: none;
        border-bottom: 1px solid #1f2d3d;
    }
    .bop-sim-status-cards {
        grid-template-columns: 1fr 1fr;
    }
    .bop-sim-header h1 {
        font-size: 1.1rem;
    }
    .bop-sim-value {
        font-size: 1.5rem;
    }
}

