                    if (d.r1_answers && d.r1_answers[i] === this.R1_CORRECT[i]) {
                        correctCount++;
                        roundScore += 20;
                    }
                }
                feedback = trf('fb_r1', correctCount);
            } else if (round === 2) {
                totalQuestions = 3;
                if (Math.abs((d.r2_net || 0) - (-60)) <= 5) { correctCount++; roundScore += 34; }
                if (d.r2_sector === 'finance') { correctCount++; roundScore += 33; }
                if (d.r2_region === 'eu') { correctCount++; roundScore += 33; }
                feedback = trf('fb_r2', correctCount);
            } else if (round === 3) {
                totalQuestions = 5;
                for (var j = 0; j < 4; j++) {
                    if (d.r3_answers && d.r3_answers[j] === this.R3_CORRECT[j]) {
                        correctCount++;
                        roundScore += 20;
                    }
                }
                if (d.r3_verdict === 'vulnerable') {
                    correctCount++;
                    roundScore += 20;
                } else if (d.r3_verdict === 'mixed') {
                    roundScore += 10;
                }
                feedback = trf('fb_r3', correctCount);
            } else if (round === 4) {
                totalQuestions = 4;
                if (d.r4_m3 === 'worsens') { correctCount++; roundScore += 25; }
                if (d.r4_m12 === 'improves') { correctCount++; roundScore += 25; }
                if (d.r4_m18 === 'improves') { correctCount++; roundScore += 25; }
                if (d.r4_ml === 'yes') { correctCount++; roundScore += 25; }
                feedback = trf('fb_r4', correctCount);
            } else if (round === 5) {
                totalQuestions = 3;
                var good = ['nothing', 'exports', 'fdi'];
                var bad = ['tariffs', 'austerity', 'depreciate'];
                var picks = d.r5_picks || [];
                for (var k = 0; k < picks.length; k++) {
                    if (good.indexOf(picks[k]) >= 0) {
                        roundScore += 40;
                        correctCount++;
                    } else if (bad.indexOf(picks[k]) >= 0) {
                        roundScore -= 5;
                    }
                }
                if (d.r5_factor === 'financing') {
                    roundScore += 20;
                    correctCount++;
                }
                feedback = trf('fb_r5', correctCount);
            }

            if (roundScore > 100) roundScore = 100;
            if (roundScore < 0) roundScore = 0;

            state.domainState.totalScore += roundScore;
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.accuracyHistory.push(totalQuestions > 0 ? Math.round(100 * correctCount / totalQuestions) : 0);

            // platform score: running average of the round scores so far, so the last round equals totalScore out of 500 scaled to 0-100 (verdict bands 450, 350, 200 become 90, 70, 40)
            var playedSoFar = state.domainState.scoreHistory.length || 1;
            var runningScore = Math.round(state.domainState.totalScore / playedSoFar);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, runningScore)) });

            var total = state.domainState.totalScore;
            if (total >= 450) state.domainState.stars = 3;
            else if (total >= 300) state.domainState.stars = 2;
            else state.domainState.stars = 1;

            if (total >= 450) state.domainState.rank = 'Chief Economist';
            else if (total >= 350) state.domainState.rank = 'Analyst';
            else if (total >= 200) state.domainState.rank = 'Statistician';
            else state.domainState.rank = 'Trainee';

            // v1.1.0: racy setTimeout briefing refresh removed. It read the period at FIRE time
            // (after the framework advanced it) -> the briefing jumped to round N+2 on submit; it also
            // never refreshed on undo. Now wired to the framework's real lifecycle events in setupUI().

            return {
                period: round,
                roundScore: roundScore,
                correct: correctCount,
                total: totalQuestions,
                totalScore: state.domainState.totalScore,
                feedback: feedback
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore', function(v) {
                return Math.round(v || 0) + ' pts';
            });
            uiManager.bind('starsDisplay', 'domainState.stars', function(v) {
                var n = v || 0;
                var out = '';
                for (var i = 0; i < 3; i++) out += (i < n ? '⭐' : '☆');
                return out;
            });
            uiManager.bind('rankDisplay', 'domainState.rank', function(v) {
                var map = { 'Trainee': 'rank_trainee', 'Statistician': 'rank_statistician', 'Analyst': 'rank_analyst', 'Chief Economist': 'rank_chief' };
                if (!map[v]) return v;
                try { var out = window.mySimulation.t(map[v]); return (out && out !== map[v]) ? out : v; } catch (e) { return v; }
            });

            // v1.1.0: keep the briefing in sync with the framework's real lifecycle. currentPeriod
            // is already advanced/restored by the time these fire, so the live round is always shown
            // (fixes N+2 desync on submit and stale briefing on undo/language switch).
            if (!this._wired) {
                this._wired = true;
                var self = this;
                var refresh = function() {
                    var sim = window.mySimulation;
                    if (sim && sim.state) self._updateBriefing(sim.state);
                };
                var sim = window.mySimulation;
                if (sim && sim.eventBus && typeof sim.eventBus.on === 'function') {
                    sim.eventBus.on('period:submitted', refresh);
                    sim.eventBus.on('period:undone', refresh);
                }
                document.addEventListener('express:langchanged', refresh);
            }
        }

