        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = history.reduce(function(s, r) {
                return s + (r.results && r.results.roundScore ? r.results.roundScore : 0);
            }, 0);
            var avg = totalScore / history.length;
            var ts = function(k) {
                try { var v = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; return (v == null) ? k : v; } catch (e) { return k; }
            };
            var performance = ts('rank_trainee');
            if (totalScore >= 450) performance = ts('rank_chief');
            else if (totalScore >= 350) performance = ts('rank_analyst');
            else if (totalScore >= 200) performance = ts('rank_statistician');

            var insights = [];
            if (totalScore >= 450) {
                insights.push(ts('ins_master'));
            } else if (totalScore >= 300) {
                insights.push(ts('ins_solid'));
            } else {
                insights.push(ts('ins_revisit'));
            }
            insights.push(ts('ins_balance'));
            return {
                totalScore: totalScore,
                avgScore: avg,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (typeof results.roundScore === 'number' && results.roundScore < 40) {
                return window.mySimulation.t('hint_low');
            }
            if (typeof results.roundScore === 'number' && results.roundScore >= 80) {
                return window.mySimulation.t('hint_high');
            }
            if (state.domainState && state.domainState.totalScore >= 450) {
                return window.mySimulation.t('hint_chief');
            }
            return null;
        }

